ee:message.ee:set-payload:
%dw 2.0
output application/json
var result = payload.result default {}
---
{
	statusCode: "OK",
	statusDetail: payload.res_message default "Success",
	result: {
		resultCode: result.resultCode default result.responseCode default "0000",
		resultMessage: result.resultMsg default result.responseMessage default "success",
		orderNumber: result.workOrderId default vars.initialPayload.orderNumber
	}
}

%dw 2.0
output application/json
---
{
	statusCode: "NOK",
	statusDetail: error.description,
	result: {
		resultCode: "9999",
		resultMessage: error.description,
		orderNumber: vars.initialPayload.orderNumber default ""
	}
}

%dw 2.0
output application/json
---
{
	statusCode: "NOK",
	statusDetail: error.description,
	result: {
		resultCode: "9999",
		resultMessage: error.description,
		orderNumber: vars.initialPayload.orderNumber default ""
	}
}

%dw 2.0
output application/json
var status = (error.errorMessage.attributes.statusCode default "500") as String
var body = error.errorMessage.payload default {}
var detail = if (body is Object) write(body, "application/json")
	else (body as String default error.description)
---
{
	statusCode: "NOK",
	statusDetail: "HTTP " ++ status ++ " from ZSmart: " ++ detail,
	result: {
		resultCode: "9999",
		resultMessage: detail,
		orderNumber: vars.initialPayload.orderNumber default ""
	}
}
